using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using EFT;
using UnityEngine;
namespace LocalSpt5Esp;
internal static partial class RaidCommands {
 static void Teleport(GameWorld w,string[] a){Require(a,1);int facing=Array.IndexOf(a,"facing");var move=facing<0?a:a[..facing];string[] facingArgs=facing<0?Array.Empty<string>():a[(facing+1)..];Player[] targets;Vector3 goal;if(move.Length==1){targets=new[]{w.MainPlayer};goal=Destination(w,move[0]);}else if(move.Length==2){targets=Resolve(w,move[0]);goal=Destination(w,move[1]);}else if(move.Length==3){targets=new[]{w.MainPlayer};goal=Coordinates(w,move);}else if(move.Length==4){targets=Resolve(w,move[0]);goal=Coordinates(w,move[1..]);}else throw new ArgumentException("/tp [来源] <目标|x y z> [facing <目标|x y z>]");Vector3? look=facingArgs.Length==0?null:facingArgs.Length==1?Destination(w,facingArgs[0]):Coordinates(w,facingArgs);foreach(var p in targets){if(p.IsYourPlayer)back=p.Position;TeleportControl.ChatMove(p,goal);if(look.HasValue){var angle=DirectorRules.Look(new(look.Value.x-p.Position.x,look.Value.y-p.Position.y,look.Value.z-p.Position.z),p.Rotation.x);if(p.IsYourPlayer)p.Rotation=new(angle.X,angle.Y);else AiSceneDirector.Apply(w,p,AiSceneDirector.For(p) with{Enabled=true,SetFacing=true,Yaw=angle.X,Pitch=angle.Y});}}RaidChat.Output("已传送 "+targets.Length+" 个对象。AI 在无落脚点位置会保持固定。");}
 static void Inspect(GameWorld w,string[] a){Require(a,1);string field=a.Length>1?a[1]:"all";if(field is not ("all" or "health" or "equipment" or "effects" or "position"))throw new ArgumentException("属性类型：health、equipment、effects、position。");foreach(var p in Resolve(w,a[0])){RaidChat.Output(Type(p)+":"+Name(p)+" uuid:"+Id(p)+" · "+Role(p));if(field is "all" or "position")RaidChat.Output("position "+p.Position.ToString("F2"));if(field is "all" or "health")RaidChat.Output(JsonSerializer.Serialize(AiBodyHealth.Capture(p)));if(field is "all" or "equipment")RaidChat.Output(string.Join(" · ",InventorySlots(p).Select(s=>s.Name+": "+(s.ContainedItem==null?"empty":LootDisplay.ItemName(s.ContainedItem,false)))));if(field is "all" or "effects")RaidChat.Output(JsonSerializer.Serialize(CharacterBuffs.CaptureSceneDetailed(p)));}}
 static EBodyPart Body(string value)=>Enum.TryParse<EBodyPart>(value,true,out var part)&&Enum.IsDefined(part)?part:throw new ArgumentException("部位：Head Chest Stomach LeftArm RightArm LeftLeg RightLeg Common。");
 static void Damage(GameWorld w,string[] a){Require(a,2);float amount=(float)ChatCommandSyntax.Number(a[1],0,100000000);EDamageType type=a.Length>2&&Enum.TryParse<EDamageType>(a[2],true,out var t)&&Enum.IsDefined(t)?t:EDamageType.Bullet;if(a.Length>2&&(!Enum.TryParse<EDamageType>(a[2],true,out var checkedType)||!Enum.IsDefined(checkedType)))throw new ArgumentException("未知伤害类型。");var part=a.Length>3?Body(a[3]):EBodyPart.Chest;if(part==EBodyPart.Common)throw new ArgumentException("伤害需要具体部位。");var targets=Ai(w,a[0]);foreach(var p in targets){var info=new EFT.Ballistics.DamageInfo{DamageType=type,Damage=amount,Player=new PlayerBridge(w.MainPlayer).Cast<IObserverToPlayerBridge>(),MasterOrigin=w.MainPlayer.Position,HitPoint=p.Position+Vector3.up,Direction=(p.Position-w.MainPlayer.Position).normalized,SourceId="assistant-command"};p.LastAggressor=w.MainPlayer;p.ActiveHealthController.ApplyDamage(part,amount,info);}RaidChat.Output("已提交伤害 ×"+targets.Length+"；实际伤害仍受护甲、无敌和伤害倍率影响。");}
 static void Heal(GameWorld w,string[] a){var targets=Resolve(w,a.Length==0?"@s":a[0]);var part=a.Length>1?Body(a[1]):EBodyPart.Common;foreach(var p in targets){var health=p.ActiveHealthController??throw new ArgumentException("生命控制器未就绪。");foreach(var body in part==EBodyPart.Common?new[]{EBodyPart.Head,EBodyPart.Chest,EBodyPart.Stomach,EBodyPart.LeftArm,EBodyPart.RightArm,EBodyPart.LeftLeg,EBodyPart.RightLeg}:new[]{part}){health.RemoveNegativeEffects(body);health.FullRestoreBodyPart(body);}if(part==EBodyPart.Common){health.RemoveNegativeEffects(part);health.RestoreFullHealth();health.ChangeHydration(health.Hydration.Maximum-health.Hydration.Current);health.ChangeEnergy(health.Energy.Maximum-health.Energy.Current);health.RemoveIntoxication();}}RaidChat.Output("已治疗 "+targets.Length+" 个对象。");}
 static void Effect(GameWorld w,string[] a){Require(a,2);if(a[0]=="give"){Require(a,3);string type=BuffRules.Common.FirstOrDefault(b=>b.Type.Equals(a[2],StringComparison.OrdinalIgnoreCase))?.Type??throw new ArgumentException("未知效果；按 Tab 查看支持的效果。");float seconds=a.Length>3?(float)ChatCommandSyntax.Number(a[3],1,86400):30,strength=a.Length>4?(float)ChatCommandSyntax.Number(a[4],.01,1000000):1;var part=a.Length>5?Body(a[5]):EBodyPart.Chest;foreach(var p in Resolve(w,a[1]))CharacterBuffs.AddBirthBuff(w,p,type,part,seconds,strength);}else if(a[0]=="clear")foreach(var p in Resolve(w,a[1]))CharacterBuffs.ChatClear(p,a.Length>2?a[2]:null);else throw new ArgumentException("/effect give|clear ...");RaidChat.Output("效果操作已完成；环境或伤势可能再次触发效果。");}
 static void Summon(GameWorld w,string[] a){Require(a,1);Vector3 point=a.Length>=4?Coordinates(w,a[1..4]):w.MainPlayer.Position+w.MainPlayer.Transform.forward*3;int count=a.Length>4?(int)ChatCommandSyntax.Number(a[4],1,32):1,difficulty=a.Length>5?(int)ChatCommandSyntax.Number(a[5],0,3):1;if(a[0].StartsWith("template:",StringComparison.OrdinalIgnoreCase)){var template=SceneTemplates.ChatTemplate(a[0][9..]);SceneTemplates.Spawn(w,point,template with{Count=count,Difficulty=difficulty});}else{string role=a[0].ToLowerInvariant() switch{"scav"=>"assault","usec"=>"pmcUSEC","bear"=>"pmcBEAR","raider"=>"pmcBot","rogue"=>"exUsec",_=>a[0]};var option=AiSpawnCatalog.Options.FirstOrDefault(o=>o.Role.Equals(role,StringComparison.OrdinalIgnoreCase))??throw new ArgumentException("未知 AI 角色；Tab 补全原生角色名。");AiSpawnService.Enqueue(w,point,option,difficulty,count,new AiBirthPreset(0,100,false,false,false,0,0,Array.Empty<string>(),EBodyPart.Chest,30,1),"聊天命令");}RaidChat.Output("已加入 AI 生成队列。/summon 仍需等待原生资源和角色初始化。");}
 static void Tag(GameWorld w,string[] a){Require(a,2);var targets=Resolve(w,a[0]);if(a[1] is not ("add" or "remove" or "list"))throw new ArgumentException("/tag <目标> add|remove|list [标签]");if(a[1]!="list")Require(a,3);foreach(var p in targets){string id=Id(p);if(!tags.TryGetValue(id,out var set))tags[id]=set=new();if(a[1]=="add"){if(a[2].Length>64||set.Count>=64)throw new ArgumentException("每个对象最多64个标签，每个标签最多64字符。");set.Add(a[2]);}else if(a[1]=="remove")set.Remove(a[2]);RaidChat.Output(Name(p)+": "+string.Join(", ",set));}}
 static void ControlAi(GameWorld w,string[] a){Require(a,2);var targets=Ai(w,a[1]);switch(a[0]){case "pause":AiTestControl.SetPaused(targets,true);break;case "resume":foreach(var p in targets){AiFreePlacement.Release(p);AiSceneDirector.Remove(p);}AiTestControl.SetPaused(targets,false);break;case "anchor":if(a.Length>2&&a[2] is not ("on" or "off"))throw new ArgumentException("/ai anchor <AI> [on|off]");foreach(var p in targets){if(a.Length>2&&a[2]=="off")AiFreePlacement.Release(p);else AiFreePlacement.Place(w,p,p.Position);}break;case "follow":case "look":foreach(var p in targets){if(a.Length>2&&a[2]!="@s"&&One(w,a[2]).Pointer!=w.MainPlayer.Pointer)throw new ArgumentException("当前导演只支持跟随或看向本地玩家 @s。");var settings=AiSceneDirector.For(p);var action=a[0]=="follow"?SceneActions.FollowPlayer:SceneActions.LookAtPlayer;AiSceneDirector.Apply(w,p,settings with{Enabled=true,Actions=settings.Actions|action,SetFacing=false});}break;case "pose":Require(a,3);if(!Enum.TryParse<ScenePose>(a[2],true,out var pose)||!Enum.IsDefined(pose))throw new ArgumentException("姿势为 standing、crouched、prone、original。");foreach(var p in targets)AiSceneDirector.Apply(w,p,AiSceneDirector.For(p) with{Enabled=true,Pose=pose});break;case "relation":Require(a,3);if(a[2] is not ("neutral" or "hostile" or "default"))throw new ArgumentException("关系为 neutral、hostile、default。");AiActorControl.ChatRelation(w,targets,a[2]);break;case "remove":AiActorControl.Delete(targets);break;default:throw new ArgumentException("/ai pause|resume|follow|look|pose|relation|anchor|remove <AI> [参数]");}RaidChat.Output("AI 操作已完成 ×"+targets.Length);}
 static void Data(GameWorld w,string[] a){Require(a,3);if(a[1]!="entity")throw new ArgumentException("仅支持 data ... entity。");if(a[0]=="get"){Inspect(w,new[]{a[2],a.Length>3?a[3]:"all"});return;}if(a.Length!=7||a[0]!="modify"||a[4]!="set"||a[5]!="value")throw new ArgumentException("/data modify entity <AI> <字段> set value <值>；字段只支持 name、invincible、damageMultiplier。");if(a[3]=="name")Execute("rename",new[]{a[2],a[6]});else Attribute(w,new[]{a[2],a[3],"base","set",a[6]});
 }
 static void Attribute(GameWorld w,string[] a){Require(a,4);if(a[2]!="base"||a[3] is not ("get" or "set"))throw new ArgumentException("/attribute <目标> <属性> base get|set [值]");var targets=Ai(w,a[0]);foreach(var p in targets){var state=AiActorControl.EditorState(p);if(a[3]=="get"){RaidChat.Output(Name(p)+" "+a[1]+" = "+(a[1]=="invincible"?state.Invincible.ToString():a[1]=="damageMultiplier"?state.Damage.ToString():throw new ArgumentException("属性支持 invincible、damageMultiplier。")));continue;}Require(a,5);if(a[1]=="invincible")AiActorControl.ApplyEditorState(w,p,Boolean(a[4]),state.Damage);else if(a[1]=="damageMultiplier")AiActorControl.ApplyEditorState(w,p,state.Invincible,(float)ChatCommandSyntax.Number(a[4],0,1000000));else throw new ArgumentException("属性支持 invincible、damageMultiplier。");}RaidChat.Output("属性操作已完成。");}
 static bool Boolean(string value)=>value.ToLowerInvariant() switch{"true" or "on" or "1"=>true,"false" or "off" or "0"=>false,_=>throw new ArgumentException("布尔值为 true 或 false。")};
 static void Spread(GameWorld w,string[] a){Require(a,5);float x=(float)ChatCommandSyntax.Number(a[0],-100000,100000),z=(float)ChatCommandSyntax.Number(a[1],-100000,100000),spacing=(float)ChatCommandSyntax.Number(a[2],.5,1000),range=(float)ChatCommandSyntax.Number(a[3],1,10000);var targets=Resolve(w,a[4]);var planned=new List<Vector3>();foreach(var p in targets){Vector3? position=null;for(int n=0;n<1000;n++){var offset=UnityEngine.Random.insideUnitCircle*range;var candidate=new Vector3(x+offset.x,w.MainPlayer.Position.y,z+offset.y);if(planned.All(q=>Vector3.Distance(q,candidate)>=spacing)&&UnityEngine.AI.NavMesh.SamplePosition(candidate,out var nav,4,UnityEngine.AI.NavMesh.AllAreas)){position=nav.position;break;}}if(position==null)throw new ArgumentException("无法在给定范围规划足够间距；没有移动对象。");planned.Add(position.Value);}for(int i=0;i<targets.Length;i++){if(targets[i].IsYourPlayer)back=targets[i].Position;TeleportControl.ChatMove(targets[i],planned[i]);}RaidChat.Output("已分散 "+targets.Length+" 个对象。");}
}
